import{_ as t,a as o,b as a}from"./chunks/6.C90syIqY.js";import{_ as r,a as s,b as i,c as l,d as n,e as u,f as c}from"./chunks/16.CEuEpGbu.js";import{_ as d}from"./chunks/17.CpKVWXAe.js";import{_ as h,o as p,c as g,a0 as m}from"./chunks/framework.DRjqbEpm.js";const x=JSON.parse('{"title":"🎛️ Dashboard Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/dashboard.md","filePath":"en/guide/dashboard.md"}'),b={name:"en/guide/dashboard.md"};function k(f,e,y,v,q,w){return p(),g("div",null,[...e[0]||(e[0]=[m('<h1 id="🎛️-dashboard-overview" tabindex="-1">🎛️ Dashboard Overview <a class="header-anchor" href="#🎛️-dashboard-overview" aria-label="Permalink to &quot;🎛️ Dashboard Overview&quot;">​</a></h1><p>The V-Train Dashboard is the main control center. It is like an airplane&#39;s cockpit where you find all the buttons and switches! This page explains what each part does.</p><blockquote><p><img src="'+t+'" alt="Dashboard Main Screen"></p></blockquote><div class="info custom-block"><p class="custom-block-title">📋 How to open the Dashboard?</p><p>Click the <strong>VT icon</strong> on your Chrome toolbar. If you have a passcode, you must enter it first.</p></div><hr><h2 id="_1-dashboard-layout" tabindex="-1">1. Dashboard Layout <a class="header-anchor" href="#_1-dashboard-layout" aria-label="Permalink to &quot;1. Dashboard Layout&quot;">​</a></h2><p>From top to bottom, the dashboard has these main areas:</p><table tabindex="0"><thead><tr><th>Area</th><th>Function</th></tr></thead><tbody><tr><td>🔴 Status Area</td><td>Switch between Monitoring / Monitoring Off</td></tr><tr><td>⚙️ Settings</td><td>Hover Panel, Monitor Panel, Progress Bar Color, Language</td></tr><tr><td>🌐 Authorize</td><td>Authorize the current website</td></tr><tr><td>📊 Statistics</td><td>Number of recorded videos</td></tr><tr><td>🗂️ Quick Actions</td><td>Rules, Bookmark Vault, Backup, Unlock Pro</td></tr><tr><td>🔒 Privacy</td><td>Passcode, Clear Data</td></tr></tbody></table><hr><h2 id="_2-status-area-monitoring-monitoring-off" tabindex="-1">2. Status Area: Monitoring / Monitoring Off <a class="header-anchor" href="#_2-status-area-monitoring-monitoring-off" aria-label="Permalink to &quot;2. Status Area: Monitoring / Monitoring Off&quot;">​</a></h2><p>This is the most important switch. It controls if V-Train is &quot;working&quot;.</p><blockquote><p><img src="'+o+'" alt="Monitoring Toggle"></p></blockquote><h3 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h3><ul><li>Switch is ON → Green light, text says &quot;Monitoring&quot;</li><li>V-Train is tracking the videos you watch.</li><li>Progress bars appear under video thumbnails.</li></ul><h3 id="monitoring-off" tabindex="-1">Monitoring Off <a class="header-anchor" href="#monitoring-off" aria-label="Permalink to &quot;Monitoring Off&quot;">​</a></h3><ul><li>Switch is OFF → Gray light, text says &quot;Monitoring Off&quot;</li><li>V-Train is sleeping. <strong>It will not record or show</strong> progress bars.</li><li>It leaves no trace of what you watch.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 When should I use Monitoring Off?</p><p>Use Monitoring Off when you watch videos you do not want to record. You can switch modes at any time.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ Monitoring Off is default for new users</p><p>When you first install V-Train, <strong>Monitoring Off is turned on by default</strong>. If you do not see progress bars, please make sure the switch is set to &quot;Monitoring&quot;.</p></div><hr><h2 id="_3-settings-area" tabindex="-1">3. Settings Area <a class="header-anchor" href="#_3-settings-area" aria-label="Permalink to &quot;3. Settings Area&quot;">​</a></h2><h3 id="🖱️-hover-panel-show-interaction" tabindex="-1">🖱️ Hover Panel (Show Interaction) <a class="header-anchor" href="#🖱️-hover-panel-show-interaction" aria-label="Permalink to &quot;🖱️ Hover Panel (Show Interaction)&quot;">​</a></h3><p>This controls the &quot;Floating Panel&quot; on the video playback screen.</p><p>This small panel lets you:</p><ul><li><strong>👍 Like / 👎 Dislike</strong> — Rate the video quickly.</li><li><strong>❤️ Bookmark</strong> — Save the video to your Bookmark Vault.</li><li><strong>📸 Snapshot Cover</strong> — Take a picture of the video to use as a cover.</li></ul><blockquote><p><img src="'+r+'" alt="Floating Interaction Panel"></p></blockquote><p>If you do not like this panel, you can turn it off here.</p><div class="info custom-block"><p class="custom-block-title">Free vs Pro Version</p><p>Free users can use all buttons on the Hover Panel. Free users can save up to <strong>100 bookmarks</strong>. Upgrading to Pro gives you unlimited bookmarks.</p></div><hr><h3 id="🖥️-monitor-panel" tabindex="-1">🖥️ Monitor Panel <a class="header-anchor" href="#🖥️-monitor-panel" aria-label="Permalink to &quot;🖥️ Monitor Panel&quot;">​</a></h3><p>This is a tool to help fix problems. If you turn it on, a small black window appears in the <strong>bottom left</strong> corner of your screen. It shows what V-Train is doing:</p><ul><li>Is it recording?</li><li>What is the Video ID?</li><li>What is the current progress (%)?</li></ul><blockquote><p><img src="'+s+'" alt="Monitor Panel"></p></blockquote><p>Normal users do not need to turn this on. It is useful if progress bars are not working properly.</p><div class="tip custom-block"><p class="custom-block-title">💡 When is it useful?</p><p>When you train a new website, the rules might not work. Turn on the monitor panel to see what ID the system finds. This helps you fix mistakes!</p></div><hr><h3 id="🎨-progress-bar-color" tabindex="-1">🎨 Progress Bar Color <a class="header-anchor" href="#🎨-progress-bar-color" aria-label="Permalink to &quot;🎨 Progress Bar Color&quot;">​</a></h3><p>Do you want to change the <strong>red</strong> progress bar? Click the color square. A color picker will open. You can choose any color!</p><blockquote><p><img src="'+i+'" alt="Progress Bar Color Picker"></p></blockquote><ul><li>The color saves immediately.</li><li>All trained websites will use this new color.</li><li>To switch back to red, type <code>#ff0000</code> in the color picker.</li></ul><hr><h3 id="🌐-language-select" tabindex="-1">🌐 Language Select <a class="header-anchor" href="#🌐-language-select" aria-label="Permalink to &quot;🌐 Language Select&quot;">​</a></h3><p>Use the menu at the top right to change the language.</p><table tabindex="0"><thead><tr><th>Option</th><th>Language</th></tr></thead><tbody><tr><td><code>zh-TW</code></td><td>Traditional Chinese</td></tr><tr><td><code>en</code></td><td>English</td></tr></tbody></table><p>The text changes immediately. You do not need to refresh the page.</p><div class="info custom-block"><p class="custom-block-title">Multi-language Support</p><p>The extension supports multiple languages. We will add more languages to the manual soon.</p></div><hr><h2 id="_4-authorize-current-site-button" tabindex="-1">4. Authorize Current Site Button <a class="header-anchor" href="#_4-authorize-current-site-button" aria-label="Permalink to &quot;4. Authorize Current Site Button&quot;">​</a></h2><blockquote><p><img src="'+a+'" alt="Authorize Button"></p></blockquote><p>This <strong>blue button</strong> is at the <strong>very top</strong> of the dashboard. If you visit a website that is <strong>not authorized</strong>, the button says:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔓 Authorize &amp; Enable Current Site</span></span></code></pre></div><p>Click it. Chrome will ask for permission. Click Allow. The button will turn <strong>green</strong> and say:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ Site Authorized</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">📌 V-Train&#39;s Authorization System</p><p>V-Train uses Chrome&#39;s <strong>Optional Permissions</strong>. It only works on websites you allow. It cannot read data from other websites. Your privacy is safe.</p></div><hr><h2 id="_5-statistics-video-record-count" tabindex="-1">5. Statistics: Video Record Count <a class="header-anchor" href="#_5-statistics-video-record-count" aria-label="Permalink to &quot;5. Statistics: Video Record Count&quot;">​</a></h2><p>The middle of the dashboard shows how many <strong>video progress records</strong> V-Train has saved.</p><ul><li><strong>Free Version</strong>: Shows <code>{Count} / 200</code> (Maximum 200 records)</li><li><strong>Pro Version</strong>: Shows <code>{Count} / ∞ PRO</code> (Unlimited, gold text)</li></ul><p>For free users, the number turns <strong>red</strong> when you get close to 200. When you reach 200, new records will delete the oldest records.</p><hr><h2 id="_6-trained-sites-management-rules-panel" tabindex="-1">6. Trained Sites Management (Rules Panel) <a class="header-anchor" href="#_6-trained-sites-management-rules-panel" aria-label="Permalink to &quot;6. Trained Sites Management (Rules Panel)&quot;">​</a></h2><p>Click the &quot;<strong>Trained Sites (Rules)</strong>&quot; button to open the rules management panel.</p><blockquote><p><img src="'+l+'" alt="Rules Management Panel"></p></blockquote><h3 id="🔍-search" tabindex="-1">🔍 Search <a class="header-anchor" href="#🔍-search" aria-label="Permalink to &quot;🔍 Search&quot;">​</a></h3><p>Use the search box at the top. Type a website name (like <code>example.com</code>) to find it quickly.</p><h3 id="📄-pages" tabindex="-1">📄 Pages <a class="header-anchor" href="#📄-pages" aria-label="Permalink to &quot;📄 Pages&quot;">​</a></h3><p>The list shows <strong>10 websites</strong> per page. Use the buttons to go to the next or previous page.</p><h3 id="📋-rule-details" tabindex="-1">📋 Rule Details <a class="header-anchor" href="#📋-rule-details" aria-label="Permalink to &quot;📋 Rule Details&quot;">​</a></h3><p>Click a website name to <strong>see more details</strong>:</p><ul><li><strong>Slot Dots</strong>: There are 4 training slots (Mod 1 ~ Mod 4). A red dot ● means a rule is saved here. A gray dot ○ means it is empty.</li><li><strong>Rule Description</strong>: Explains how the rule works (like &quot;Last segment of URL path&quot;).</li><li><strong>Raw JSON</strong>: Click to see the code data.</li><li><strong>VT-RULE Serial Number</strong>: Every rule has a special serial number you can share.</li></ul><blockquote><p><img src="'+n+'" alt="Rule Detail Card"></p></blockquote><h3 id="📤-share-rules-copy-serial" tabindex="-1">📤 Share Rules (Copy Serial) <a class="header-anchor" href="#📤-share-rules-copy-serial" aria-label="Permalink to &quot;📤 Share Rules (Copy Serial)&quot;">​</a></h3><p>Click the <strong>orange &quot;📋 Share&quot; button</strong> on a rule card. The full <code>VT-RULE-Z...</code> serial number will copy to your clipboard. You can paste it to share with friends!</p><div class="tip custom-block"><p class="custom-block-title">💡 Full Serial Number</p><p>The dashboard only shows part of the serial number to save space. If you <strong>hover your mouse</strong> over it, you will see the full number. The Share button always copies the full number.</p></div><h3 id="🗑️-delete-rules" tabindex="-1">🗑️ Delete Rules <a class="header-anchor" href="#🗑️-delete-rules" aria-label="Permalink to &quot;🗑️ Delete Rules&quot;">​</a></h3><p>Click the trash can icon 🗑️ to delete a rule. You must click confirm to delete it.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Cannot be undone</p><p>If you delete a rule, you cannot get it back. Use &quot;Share&quot; to copy the serial number as a backup before you delete it!</p></div><h3 id="📥-import-rules" tabindex="-1">📥 Import Rules <a class="header-anchor" href="#📥-import-rules" aria-label="Permalink to &quot;📥 Import Rules&quot;">​</a></h3><p><strong>Method 1: Paste Serial Number</strong> Find the serial input box. Paste the <code>VT-RULE-Z...</code> serial number. Click the &quot;<strong>Import</strong>&quot; button.</p><p><strong>Method 2: Import JSON File</strong> Click the &quot;<strong>Import File</strong>&quot; button. Choose a <code>VTrain_Rules_XXXX-XX-XX.json</code> file. The system will add these rules.</p><div class="info custom-block"><p class="custom-block-title">📌 Community Rules Library</p><p>Do you not want to train websites yourself? Visit the <a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">Community Rules Library</a>. Copy a rule from there and import it!</p></div><hr><h2 id="_7-bookmark-vault-access" tabindex="-1">7. Bookmark Vault Access <a class="header-anchor" href="#_7-bookmark-vault-access" aria-label="Permalink to &quot;7. Bookmark Vault Access&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">👑 Pro Feature</p><p>The Bookmark Vault is a <strong>V-Train Pro</strong> feature.</p></div><p>Click the &quot;<strong>📚 Bookmark Vault</strong>&quot; button. A beautiful full-screen bookmark manager will open in a new tab.</p><blockquote><p><img src="'+u+'" alt="Bookmark Vault Main Screen"></p></blockquote><p>Bookmark Vault features:</p><ul><li><strong>Folders</strong>: Create many folders. Right-click to rename or delete.</li><li><strong>Bookmark Cards</strong>: Each video has a cover picture, title, and link.</li><li><strong>Quick Jump</strong>: Click a card to open the video in a new tab.</li><li><strong>Custom Covers</strong>: Take pictures of the video to use as covers.</li></ul><p>To learn more, read the <a href="./bookmark-vault.html">Bookmark Vault Guide</a>.</p><hr><h2 id="_8-backup-restore" tabindex="-1">8. Backup &amp; Restore <a class="header-anchor" href="#_8-backup-restore" aria-label="Permalink to &quot;8. Backup &amp; Restore&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">⚠️ Important! Backup your data!</p><p>V-Train stores all data <strong>only on your computer</strong>. We have no servers. If you remove the extension or reinstall your browser, your data is gone forever!</p></div><h3 id="📥-export-backup" tabindex="-1">📥 Export Backup <a class="header-anchor" href="#📥-export-backup" aria-label="Permalink to &quot;📥 Export Backup&quot;">​</a></h3><p>Click the &quot;<strong>Export Full Backup</strong>&quot; button. The Backup Center will open. Choose what to backup:</p><ul><li>✅ <strong>Core Data</strong>: History, settings, rules, folders.</li><li>🖼️ <strong>Images</strong>: Custom cover pictures.</li></ul><p>The system will create a backup file and download it.</p><h3 id="📤-import-restore" tabindex="-1">📤 Import (Restore) <a class="header-anchor" href="#📤-import-restore" aria-label="Permalink to &quot;📤 Import (Restore)&quot;">​</a></h3><p>Click the &quot;<strong>Import Full Backup</strong>&quot; button. The Restore Center will open. <strong>Drag and drop</strong> your downloaded backup file into the page. Your data will be restored.</p><p>To learn more, read the <a href="./backup.html">Backup Guide</a>.</p><hr><h2 id="_9-pro-upgrade" tabindex="-1">9. Pro Upgrade <a class="header-anchor" href="#_9-pro-upgrade" aria-label="Permalink to &quot;9. Pro Upgrade&quot;">​</a></h2><p>At the bottom of the dashboard is the &quot;<strong>⚡ Unlock V-Train Pro</strong>&quot; button.</p><blockquote><p><img src="'+c+'" alt="Pro Upgrade Button"></p></blockquote><h3 id="how-to-upgrade" tabindex="-1">How to upgrade? <a class="header-anchor" href="#how-to-upgrade" aria-label="Permalink to &quot;How to upgrade?&quot;">​</a></h3><ol><li>Click the &quot;<strong>⚡ Unlock V-Train Pro</strong>&quot; button.</li><li>Click &quot;<strong>Go to Purchase</strong>&quot;. A new tab will open for payment ($4.99 USD, one-time payment).</li><li>After payment, you get a License Key (like <code>XXXXXXXX-XXXXXXXX-XXXXXXXX-XXXXXXXX</code>).</li><li>Go back to the dashboard. Click the upgrade button again. Paste your License Key and click confirm.</li><li>Success! The button will turn <strong>gold 👑</strong> and say &quot;Pro Enabled&quot;.</li></ol><h3 id="pro-features-overview" tabindex="-1">Pro Features Overview <a class="header-anchor" href="#pro-features-overview" aria-label="Permalink to &quot;Pro Features Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Free Version</th><th>Pro Version</th></tr></thead><tbody><tr><td>Viewing History Limit</td><td>200 records</td><td><strong>Unlimited</strong></td></tr><tr><td>Bookmark Vault</td><td>✅ Max 100 videos</td><td>✅ <strong>Unlimited</strong></td></tr><tr><td>Floating Hover Panel</td><td>✅</td><td>✅</td></tr><tr><td>Privacy Passcode</td><td>❌</td><td>✅</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Where is my License Key saved?</p><p>Your License Key is saved securely on your computer. We do not upload your personal data. You can use the same key on a new computer.</p></div><hr><h2 id="_10-privacy-settings-area" tabindex="-1">10. Privacy Settings Area <a class="header-anchor" href="#_10-privacy-settings-area" aria-label="Permalink to &quot;10. Privacy Settings Area&quot;">​</a></h2><h3 id="🔒-setup-passcode" tabindex="-1">🔒 Setup Passcode <a class="header-anchor" href="#🔒-setup-passcode" aria-label="Permalink to &quot;🔒 Setup Passcode&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">👑 Pro Feature</p><p>The passcode lock is a <strong>V-Train Pro</strong> feature.</p></div><p>Click &quot;<strong>🔒 Setup Passcode</strong>&quot;. Type a password (like <code>1234</code>).</p><p>Now, you must enter this password every time you open the Dashboard. This protects your privacy!</p><h4 id="🆘-forgot-your-passcode" tabindex="-1">🆘 Forgot your passcode? <a class="header-anchor" href="#🆘-forgot-your-passcode" aria-label="Permalink to &quot;🆘 Forgot your passcode?&quot;">​</a></h4><p>On the passcode screen, click &quot;<strong>Forgot Passcode?</strong>&quot;.</p><ol><li>Enter your <strong>Pro License Key</strong>.</li><li>The passcode will be removed.</li><li>The system will ask if you want to backup your data (we recommend yes).</li></ol><blockquote><p><img src="'+d+'" alt="Passcode Rescue Screen"></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Remove Passcode</p><p>To remove the passcode, click &quot;Setup Passcode&quot;. <strong>Leave the box empty</strong> and click confirm.</p></div><hr><h3 id="🗑️-clear-data" tabindex="-1">🗑️ Clear Data <a class="header-anchor" href="#🗑️-clear-data" aria-label="Permalink to &quot;🗑️ Clear Data&quot;">​</a></h3><p>Click the &quot;<strong>🗑️ Clear Data</strong>&quot; button. This deletes all <strong>local viewing history</strong>.</p><p>It will delete:</p><ul><li>✅ All video progress records</li><li>✅ Bookmarks and cover pictures</li></ul><p>It will <strong>NOT</strong> delete:</p><ul><li>❌ Your Pro license</li><li>❌ Trained website rules</li><li>❌ Extension settings (Language, Color, etc.)</li></ul><div class="danger custom-block"><p class="custom-block-title">⚠️ Cannot be undone!</p><p>You cannot get this data back. Please <strong>export a backup</strong> before you clear data!</p></div><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The dashboard has many buttons, but you only need to use these the most:</p><ol><li><strong>🟢 Monitoring Toggle</strong> — Keep it ON to see progress bars.</li><li><strong>🔓 Authorize Button</strong> — Click this on every new website.</li><li><strong>📋 Rules</strong> — Share and import website rules.</li><li><strong>Export Full Backup</strong> — Backup often to protect your data.</li></ol><p>If you have questions, read the <a href="./faq.html">FAQ</a> page!</p>',131)])])}const S=h(b,[["render",k]]);export{x as __pageData,S as default};
